		slots[4] = (ulong)&result;
		int status = EditorBindings.table.uiBuilderOpsClampView(slots, slots + 4);
		if (status != Bridge.OK) {
			throw Bridge.Failure(status, "UIBuilderOps.ClampView");
		}
		return result;
	}
}
